INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7352440, 1149913, 156466, '<td valign="top">I suspect this was taken as an observer and not a participant.  Nice as a candid, but just that.</td>', 'I suspect this was taken as an observer and not a participant.  Nice as a candid, but just that.', '2015-05-22 11:46:41.000000', NULL, 1),
(7352443, 1150057, 156466, '<td valign="top">All those tilted lines.</td>', 'All those tilted lines.', '2015-05-22 11:50:23.000000', NULL, 1),
(7352446, 1150048, 156466, '<td valign="top">Trying to figure out what would bother me more, the skewed window or the tilted verticals within once you fixed it?  Since I can''t figure it out, and only I would Free Transform myself into oblivion, I won''t hold it against you.  Nice capture.</td>', 'Trying to figure out what would bother me more, the skewed window or the tilted verticals within once you fixed it?  Since I can''t figure it out, and only I would Free Transform myself into oblivion, I won''t hold it against you.  Nice capture.', '2015-05-22 11:56:14.000000', NULL, 1),
(7352449, 1150084, 156466, '<td valign="top">Not a fan of the Instagram blocking or the open hood.  Otherwise great colors.</td>', 'Not a fan of the Instagram blocking or the open hood.  Otherwise great colors.', '2015-05-22 11:58:23.000000', NULL, 1),
(7352452, 1149745, 156466, '<td valign="top">Woulda given you extra points if you''d called it "Uptown Girl"</td>', 'Woulda given you extra points if you''d called it "Uptown Girl"', '2015-05-22 11:59:36.000000', NULL, 1),
(7352455, 1150051, 156466, '<td valign="top">Too abrupt a transition on the blur.  Nice idea for the isolation but it needs to be feathered.</td>', 'Too abrupt a transition on the blur.  Nice idea for the isolation but it needs to be feathered.', '2015-05-22 12:01:47.000000', NULL, 1),
(7352456, 1150109, 156466, '<td valign="top">Would have given an extra point if you called it "I''m not really sure how it goes"</td>', 'Would have given an extra point if you called it "I''m not really sure how it goes"', '2015-05-22 12:03:16.000000', NULL, 1),
(7352460, 1149801, 156466, '<td valign="top">If the blur/movement was intentional, I still don''t like it.  I did give you a point back for actually finding a pay phone.</td>', 'If the blur/movement was intentional, I still don''t like it.  I did give you a point back for actually finding a pay phone.', '2015-05-22 12:04:25.000000', NULL, 1),
(7352461, 1150044, 156466, '<td valign="top">Looking at the floor the DoF is inconsistent with what I''d have expected to see in terms of blurring so I have to assume it was added to the wall/painting(s) in post. It distracts me more than I believe the objects in the painting would have.  If you felt the need to bring her out, in what''s a lovely capture otherwise, perhaps a mild vignette centered on her?</td>', 'Looking at the floor the DoF is inconsistent with what I''d have expected to see in terms of blurring so I have to assume it was added to the wall/painting(s) in post. It distracts me more than I believe the objects in the painting would have.  If you felt the need to bring her out, in what''s a lovely capture otherwise, perhaps a mild vignette centered on her?', '2015-05-22 12:08:23.000000', NULL, 1),
